/* GYAN PETIKA: full-width header with permanently centered brand on every page/device */
html, body { width:100% !important; max-width:100% !important; min-width:0 !important; margin:0 !important; padding:0 !important; overflow-x:hidden !important; }
#outer-wrapper, .content-outer, .content-fauxcolumn-outer, .region-inner, .main-outer, .main-inner { width:100% !important; max-width:100% !important; min-width:0 !important; margin-left:0 !important; margin-right:0 !important; }
