/* Numbered label pagination: Next / Back + page numbers */
#gp-numbered-pager{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:8px;width:100%;margin:22px auto 30px;padding:14px 10px;border-top:1px solid #dbe5ef;box-sizing:border-box}
#gp-numbered-pager a,#gp-numbered-pager span{display:inline-flex;align-items:center;justify-content:center;min-width:40px;min-height:40px;padding:8px 12px;border:1px solid #07518d;border-radius:9px;background:#fff;color:#07518d;font-size:14px;font-weight:700;text-decoration:none;box-sizing:border-box}
#gp-numbered-pager a.gp-page-current{background:#07518d;color:#fff;pointer-events:none}
#gp-numbered-pager a.gp-page-nav{background:#07518d;color:#fff}
