  body.item .columns, body.static_page .columns,
  body.item .column-center-outer, body.static_page .column-center-outer,
  body.item .column-center-inner, body.static_page .column-center-inner,
  body.item #main-wrapper, body.static_page #main-wrapper,
  body.item #main, body.static_page #main {
    box-sizing:border-box !important;
    width:100% !important; min-width:0 !important; max-width:100% !important;
    margin-left:auto !important; margin-right:auto !important;
    float:none !important;
  }
  body.item .main-inner .columns, body.static_page .main-inner .columns {
    padding-left:0 !important; padding-right:0 !important;
  }
  body.item .column-left-outer, body.item .column-right-outer,
  body.static_page .column-left-outer, body.static_page .column-right-outer {
    display:none !important; width:0 !important; min-width:0 !important;
  }
  body.item .post-outer, body.static_page .post-outer {
    display:block !important; float:none !important;
    box-sizing:border-box !important;
    width:794px !important; max-width:calc(100% - 48px) !important;
    min-width:0 !important; min-height:1123px !important;
    margin:28px auto 44px !important;
    padding:52px 56px !important;
    background:#fff !important; border:1px solid #d6dce5 !important;
    border-radius:4px !important;
    box-shadow:0 5px 24px rgba(20,40,65,.10) !important;
  }
  body.item .post, body.static_page .post,
  body.item .post-body, body.static_page .post-body {
    box-sizing:border-box !important; width:100% !important;
    min-width:0 !important; max-width:100% !important;
    margin-left:auto !important; margin-right:auto !important;
  }
}
@media screen and (max-width: 767px) {
  body { min-width:0 !important; }
  .content-outer, .content-fauxcolumn-outer, .region-inner,
  .main-outer, .main-inner { width:100% !important; min-width:0 !important; max-width:100% !important; }
}
/* GYAN PETIKA: keep the site title visible on every page */
#header, .header-outer, .header-cap-top, .header-cap-bottom {
  display: block !important;
  visibility: visible !important;
}
#header a, .header-outer a, #header .title, #header .title a {
  cursor: pointer;
}
html, body {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow-x: hidden !important;
}
.content-outer, .content-fauxcolumn-outer, .region-inner,
.main-outer, .main-inner, .footer-outer,
.main-inner .columns, .main-inner .column-center-outer,
.main-inner .column-center-inner {
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
}
.content-inner, .main-inner, .main-inner .column-center-inner {
  padding-left: 0 !important;
  padding-right: 0 !important;
}
/* Full-width page canvas */
body:not(#layout) { min-width: 0 !important; }
body:not(#layout) .content-outer,
body:not(#layout) .content-fauxcolumn-outer,
body:not(#layout) .region-inner {
  min-width: 0 !important; max-width: 100% !important; width: 100% !important;
}
/* Override the fixed 960px desktop canvas on phones. */
@media screen and (max-width: 767px) {
  html, body { min-width: 0 !important; width: 100% !important; max-width: 100% !important; overflow-x: hidden !important; }
  .content-outer, .content-fauxcolumn-outer, .region-inner,
  .main-outer, .main-inner, .header-outer, .footer-outer,
  .main-inner .columns, .main-inner .column-center-outer,
  .main-inner .column-center-inner {
    min-width: 0 !important; width: 100% !important; max-width: 100% !important;
    margin-left: 0 !important; margin-right: 0 !important;
  }
  .main-inner .columns { padding-left: 0 !important; padding-right: 0 !important; }
}
/* Final override: prevent the 960px canvas from creating mobile blank space */
html, body { width: 100% !important; max-width: 100% !important; min-width: 0 !important; }
body { min-width: 0 !important; }
.content-outer, .content-fauxcolumn-outer, .region-inner { width: 100% !important; max-width: 100% !important; min-width: 0 !important; }
@media screen and (max-width: 767px) {
  html, body, body .content-outer, body .content-fauxcolumn-outer, body .region-inner,
  body .main-outer, body .main-inner { width: 100% !important; max-width: 100% !important; min-width: 0 !important; }
}

body.script:
// GYAN PETIKA: reliable Blogger search for header search boxes on every page.
(function(){
  var searchUrl='https://gyanpetika.blogspot.com/search?q=';
  function findSearchInput(form){
    if(!form) return null;
    return form.querySelector('input[name="q"],input[type="search"],input[placeholder* = "Search"]');
  }
  document.addEventListener('submit',function(event){
    var form=event.target;
    if(!form || !form.querySelector) return;
    var input=findSearchInput(form);
    if(!input) return;
    var value=(input.value || '').trim();
    if(!value){event.preventDefault(); input.focus(); return;}
    event.preventDefault();
    window.location.href=searchUrl+encodeURIComponent(value);
  },true);
  document.addEventListener('keydown',function(event){
    if(event.key!=='Enter') return;
    var input=event.target;
    if(!input || !(input.matches('input[type="search"],input[name="q"],input[placeholder* = "Search"]'))) return;
    var value=(input.value || '').trim();
    if(!value) return;
    event.preventDefault();
    window.location.href=searchUrl+encodeURIComponent(value);
  },true);
})();

function gpToggleMobileMenu(open){
  var drawer=document.getElementById('gp-mobile-drawer');
  var overlay=document.getElementById('gp-mobile-menu-overlay');
  var toggle=document.getElementById('gp-mobile-menu-toggle');
  if(!drawer||!overlay||!toggle)return;
  drawer.classList.toggle('gp-drawer-open',!!open);
  overlay.classList.toggle('gp-overlay-open',!!open);
  drawer.setAttribute('aria-hidden',open?'false':'true');
  overlay.setAttribute('aria-hidden',open?'false':'true');
  toggle.setAttribute('aria-expanded',open?'true':'false');
  document.body.style.overflow= open ? 'hidden' : '';
}
document.addEventListener('keydown',function(event){if(event.key==='Escape')gpToggleMobileMenu(false);});

function gpToggleHeaderItems(kind,button){
  var cls=kind==='classes'?'.gp-class-extra':'.gp-subject-extra';
  var items=document.querySelectorAll('#gp-global-header '+cls);
  var opening=!button.getAttribute('data-open');
  for(var i=0;i<items.length;i++){items[i].classList.toggle('gp-open',opening);}
  button.setAttribute('data-open',opening?'1':'');
  button.textContent=opening?'− Less '+(kind==='classes'?'Classes':'Subjects'):'+ More '+(kind==='classes'?'Classes':'Subjects');
}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//
(function(){
  'use strict';
  var match=location.pathname.match(/^\/search\/label\/([^/]+)\/?$/i);
  if(!match) return;
  document.documentElement.classList.add('gp-label-route');
  document.body.classList.add('gp-label-page');
  var label;
  try{label=decodeURIComponent(match[1].replace(/\+/g,' '));}catch(e){label=match[1];}
  var container=document.querySelector('.blog-posts');
  var pager=document.getElementById('blog-pager');
  if(!container) return;

  /* Label heading: a compact back arrow and the decoded label name above the post list. */
  if(!document.getElementById('gp-label-heading')){
    var heading=document.createElement('div');
    heading.id='gp-label-heading';
    heading.className='gp-label-heading';
    var back=document.createElement('a');
    back.className='gp-label-back';
    back.href='/';
    back.setAttribute('aria-label','Go back');
    back.setAttribute('title','Go back');
    back.textContent='';
      var gpArrowSvg=document.createElementNS('http://www.w3.org/2000/svg','svg');
      gpArrowSvg.setAttribute('viewBox','0 0 24 24');
      gpArrowSvg.setAttribute('width','22');
      gpArrowSvg.setAttribute('height','22');
      gpArrowSvg.setAttribute('aria-hidden','true');
      gpArrowSvg.setAttribute('focusable','false');
      var gpArrowPath=document.createElementNS('http://www.w3.org/2000/svg','path');
      gpArrowPath.setAttribute('d','M19 12H5 M12 19l-7-7 7-7');
      gpArrowPath.setAttribute('fill','none');
      gpArrowPath.setAttribute('stroke','currentColor');
      gpArrowPath.setAttribute('stroke-width','2.4');
      gpArrowPath.setAttribute('stroke-linecap','round');
      gpArrowPath.setAttribute('stroke-linejoin','round');
      gpArrowSvg.appendChild(gpArrowPath);
      back.appendChild(gpArrowSvg);
    back.addEventListener('click',function(event){
      var ref=document.referrer;
      if(ref){
        try{if(new URL(ref,location.href).origin===location.origin){event.preventDefault();history.back();}}catch(ignore){}
      }
    });
    var name=document.createElement('h1');
    name.className='gp-label-heading-name';
    name.textContent=label;
    heading.appendChild(back);
    heading.appendChild(name);
    container.parentNode.insertBefore(heading,container);
  }
  if(!pager){pager=document.createElement('div');pager.id='blog-pager';container.parentNode.insertBefore(pager,container.nextSibling);}
  var perPage=50;
  var params=new URLSearchParams(location.search);
  var currentPage=Math.max(1,parseInt(params.get('gp-page')||'1',10)||1);
  var busy=false;
  /* Keep Blogger's server-rendered label posts visible while the optional
     JSON enhancement loads. This prevents a stuck 'Loading posts…' screen. */
  container.classList.remove('gp-label-ready');
  container.classList.remove('gp-page-loading');
  function make(tag,cls,txt){var el=document.createElement(tag);if(cls)el.className=cls;if(txt!==undefined)el.textContent=txt;return el;}
  /* Request one extra entry only to detect whether another page exists.
     Exactly 50 entries are rendered on each page. */
  function feedUrl(page,labelOverride){return location.origin+'/feeds/posts/default/-/'+encodeURIComponent(labelOverride||label)+'?alt=json&max-results='+(perPage+1)+'&start-index='+((page-1)*perPage+1);}
  function makePager(page,pages){
    var nav=make('nav','');nav.id='gp-numbered-pager';nav.setAttribute('aria-label','Label posts pages');
    function link(n,text,cls){var a=make('a',cls||'',text);var u=new URL(location.href);u.searchParams.delete('m');u.searchParams.set('gp-page',String(n));a.href=u.pathname+u.search;a.setAttribute('data-gp-page',String(n));return a;}
    if(page>1)nav.appendChild(link(page-1,'Back','gp-page-nav'));
    var first=Math.max(1,page-2),last=Math.min(pages,page+2);
    if(first>1){nav.appendChild(link(1,'1',''));if(first>2)nav.appendChild(make('span','gp-page-gap','…'));}
    for(var n=first;n<=last;n++){var a=link(n,String(n),n===page?'gp-page-current':'');if(n===page){a.setAttribute('aria-current','page');a.removeAttribute('href');a.removeAttribute('data-gp-page');}nav.appendChild(a);}
    if(last<pages){if(last<pages-1)nav.appendChild(make('span','gp-page-gap','…'));nav.appendChild(link(pages,String(pages),''));}
    if(page<pages)nav.appendChild(link(page+1,'Next','gp-page-nav'));
    return nav;
  }
  function render(data,page,updateUrl,targetUrl){
    var feed=data&&data.feed?data.feed:{};
    var entries=feed.entry||[];
    var reportedTotal=feed.openSearch$totalResults?parseInt(feed.openSearch$totalResults.$t,10):NaN;
    /* If Blogger omits openSearch$totalResults, the 51st fetched entry signals another page. */
    var inferredTotal=(page-1)*perPage + Math.min(entries.length,perPage) + (entries.length>perPage?1:0);
    var total=(isFinite(reportedTotal)&&reportedTotal>=0)
      ? Math.max(reportedTotal,inferredTotal)
      : inferredTotal;
    if(!entries.length){
      /* Blogger's native label page is the reliable fallback. If the JSON feed
         returns no entries, do not replace the native post list with a false
         'No posts found' message. This also protects labels with feed quirks. */
      container.classList.add('gp-label-ready');
      container.classList.remove('gp-page-loading');
      return;
    }
    var pages=Math.max(1,Math.ceil(total/perPage));
    page=Math.min(page,pages);
    var list=make('div','gp-label-feed-list');
    entries.slice(0,perPage).forEach(function(entry){
      var title=entry.title&&entry.title.$t?entry.title.$t:'Untitled post';
      var href='';(entry.link||[]).some(function(link){if(link.rel==='alternate'){href=link.href;return true;}return false;});
      if(!href)return;
      var item=make('div','gp-label-post-list-item');
      var h=make('h3','post-title entry-title');var a=make('a','',title);a.href=href;h.appendChild(a);item.appendChild(h);list.appendChild(item);
    });
    function commitPage(){
      var oldList=container.querySelector('.gp-label-feed-list');
      var outgoing=oldList||container;
      var reduceMotion=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function swap(){
        if(updateUrl){
          var u=targetUrl?new URL(targetUrl,location.origin):new URL(location.href);
          u.searchParams.set('gp-page',String(page));u.searchParams.delete('m');
          history.pushState({gpPage:page,gpLabel:label},'',u.pathname+u.search);
        }
        container.replaceChildren(list);
        container.classList.add('gp-label-ready');
        var newPager=makePager(page,pages);
        var existing=document.getElementById('gp-numbered-pager');
        if(pages>1){
          if(existing&&existing.parentNode)existing.parentNode.replaceChild(newPager,existing);
          else if(pager&&pager.parentNode)pager.parentNode.replaceChild(newPager,pager);
          else container.parentNode.insertBefore(newPager,container.nextSibling);
          pager=newPager;
        }else{
          if(existing&&existing.parentNode)existing.parentNode.removeChild(existing);
          pager=null;
        }
        currentPage=page;
        container.classList.remove('gp-page-loading');
      }
      /* Swap the completed page in one paint. No fade, opacity dip, or
         transform animation: avoids the blink perceived during pagination. */
      swap();
    }
    /* Commit only after the complete feed response is ready. */
    commitPage();
  }
  function loadPage(page,updateUrl){
    if(busy || page<1 || page===currentPage)return;
    busy=true;
    /* Keep the currently displayed posts and pager in place while the next
       feed is fetched. Never replace them with a loading screen. */
    container.setAttribute('aria-busy','true');
    var activePager=document.getElementById('gp-numbered-pager');
    if(activePager)activePager.setAttribute('aria-busy','true');
    fetch(feedUrl(page),{credentials:'same-origin',cache:'default'})
      .then(function(r){if(!r.ok)throw new Error('Feed HTTP '+r.status);return r.json();})
      .then(function(data){render(data,page,updateUrl);})
      .catch(function(err){
        /* A failed request must not erase the page the visitor is reading. */
        if(window.console&&console.warn)console.warn('GYAN PETIKA label feed error:',err);
      })
      .then(function(){
        busy=false;
        container.removeAttribute('aria-busy');
        var p=document.getElementById('gp-numbered-pager');
        if(p)p.removeAttribute('aria-busy');
      });
  }
  /* Initial load: fetch fresh label results while the stable loading placeholder is visible. */
  fetch(feedUrl(currentPage),{credentials:'same-origin',cache:'force-cache'})
    .then(function(r){if(!r.ok)throw new Error('Feed HTTP '+r.status);return r.json();})
    .then(function(data){render(data,currentPage,false);})
    .catch(function(err){
      container.classList.add('gp-label-ready');container.classList.remove('gp-page-loading');
      if(window.console&&console.warn)console.warn('GYAN PETIKA label feed error:',err);
    });
  function decodeLabelFromPath(path){
    var m=path.match(/^\/search\/label\/([^/]+)\/?$/i);
    if(!m)return null;
    try{return decodeURIComponent(m[1].replace(/\+/g,' '));}catch(err){return m[1];}
  }
  function navigateLabel(anchor,targetLabel){
    /* Let Blogger render the destination label page natively. The previous
       AJAX loader could remain on screen when its feed response was empty. */
    if(!targetLabel)return;
    location.href=anchor.href;
  }
  document.addEventListener('click',function(e){
    var labelAnchor=e.target&&e.target.closest?e.target.closest('a[href]'):null;
    if(labelAnchor&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){
      var targetUrl;try{targetUrl=new URL(labelAnchor.href,location.href);}catch(ignore){}
      if(targetUrl&&targetUrl.origin===location.origin){
        var targetLabel=decodeLabelFromPath(targetUrl.pathname);
        if(targetLabel&&targetLabel.toLowerCase()!==label.toLowerCase()){
          e.preventDefault();navigateLabel(labelAnchor,targetLabel);return;
        }
      }
    }
    var a=e.target&&e.target.closest?e.target.closest('#gp-numbered-pager a[data-gp-page]'):null;
    if(!a)return;
    if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
    e.preventDefault();loadPage(parseInt(a.getAttribute('data-gp-page'),10),true);
  });
  window.addEventListener('popstate',function(){
    var pathLabel=decodeLabelFromPath(location.pathname);
    var p=Math.max(1,parseInt(new URLSearchParams(location.search).get('gp-page')||'1',10)||1);
    if(pathLabel&&pathLabel.toLowerCase()!==label.toLowerCase()){
      /* A different label needs a fresh native Blogger render. */
      location.reload();
    }else if(p!==currentPage){loadPage(p,false);}
  });
})();
//

/* Android Chrome can still start a selection on nested text nodes. Cancel
   the selection gesture at capture phase for interactive controls only. */
(function () {
  var interactive = 'a,button,summary,[role="button"],[onclick],input[type="button"],input[type="submit"],input[type="reset"],.gp-class-tab,.gp-class-dropdowns,.gp-mobile-drawer,.gp-nav,.gp-subjects,.gp-expand-latest';
  function isInteractive(target) {
    if (!target || !target.closest) return false;
    return !!target.closest(interactive);
  }
  document.addEventListener('selectstart', function (event) {
    if (isInteractive(event.target)) event.preventDefault();
  }, true);
  document.addEventListener('dragstart', function (event) {
    if (isInteractive(event.target)) event.preventDefault();
  }, true);
})();

(function(){
  'use strict';
  var interactive = 'a,button,summary,[role="button"],[onclick],input[type="button"],input[type="submit"],input[type="reset"],.gp-class-dropdowns,.gp-mobile-drawer-links,.gp-main-menu,.gp-nav,.gp-subjects,.gp-classes';
  function isInteractive(node){
    if(!node) return false;
    if(node.nodeType===3) node=node.parentElement;
    return !!(node && node.nodeType===1 && (node.matches(interactive) || node.closest(interactive)));
  }
  function clearInteractiveSelection(){
    try {
      var sel=window.getSelection && window.getSelection();
      if(sel && !sel.isCollapsed && (isInteractive(sel.anchorNode) || isInteractive(sel.focusNode))) sel.removeAllRanges();
    } catch(e){}
  }
  document.addEventListener('selectstart',function(ev){
    if(isInteractive(ev.target)){ ev.preventDefault(); clearInteractiveSelection(); }
  },true);
  document.addEventListener('selectionchange',clearInteractiveSelection,true);
  document.addEventListener('contextmenu',function(ev){
    if(isInteractive(ev.target)) ev.preventDefault();
  },true);
  document.addEventListener('touchend',function(){ window.setTimeout(clearInteractiveSelection,0); },{capture:true,passive:true});
  document.addEventListener('mouseup',function(){ window.setTimeout(clearInteractiveSelection,0); },true);
})();

(function(){
  'use strict';
  var path=window.location.pathname||'';
  var params=new URLSearchParams(window.location.search||'');
  if(!/^\/search\/?$/i.test(path) || !params.has('q')) return;
  function activate(){
    if(!document.body) return;
    document.body.classList.add('gp-search-results-page','gp-search-enter');
    var list=document.querySelector('body.gp-search-results-page .blog-posts.hfeed');
    if(list){
      /* Force a fresh entrance on every search navigation, not on label archives. */
      list.querySelectorAll('.gp-label-post-list-item').forEach(function(item){
        item.style.animation='none';
        void item.offsetWidth;
        item.style.removeProperty('animation');
      });
    }
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',activate,{once:true});
  else activate();
})();

(function(){
  'use strict';
  function labelFromPath(){
    var m=location.pathname.match(/^\/search\/label\/([^/]+)\/?$/i);
    if(!m)return null;
    try{return decodeURIComponent(m[1].replace(/\+/g,' '));}catch(e){return m[1];}
  }
  function addHeading(){
    var label=labelFromPath();
    if(!label)return false;
    document.documentElement.classList.add('gp-label-route');
    if(document.body)document.body.classList.add('gp-label-page');
    var container=document.querySelector('.blog-posts');
    if(!container || !container.parentNode)return false;
    var heading=document.getElementById('gp-label-heading');
    if(!heading){
      heading=document.createElement('div');
      heading.id='gp-label-heading';
      heading.className='gp-label-heading';
      var back=document.createElement('a');
      back.className='gp-label-back';
      back.href='/';
      back.setAttribute('aria-label','Back');
      back.setAttribute('title','Back');
      back.textContent='';
      var gpArrowSvg=document.createElementNS('http://www.w3.org/2000/svg','svg');
      gpArrowSvg.setAttribute('viewBox','0 0 24 24');
      gpArrowSvg.setAttribute('width','22');
      gpArrowSvg.setAttribute('height','22');
      gpArrowSvg.setAttribute('aria-hidden','true');
      gpArrowSvg.setAttribute('focusable','false');
      var gpArrowPath=document.createElementNS('http://www.w3.org/2000/svg','path');
      gpArrowPath.setAttribute('d','M19 12H5 M12 19l-7-7 7-7');
      gpArrowPath.setAttribute('fill','none');
      gpArrowPath.setAttribute('stroke','currentColor');
      gpArrowPath.setAttribute('stroke-width','2.4');
      gpArrowPath.setAttribute('stroke-linecap','round');
      gpArrowPath.setAttribute('stroke-linejoin','round');
      gpArrowSvg.appendChild(gpArrowPath);
      back.appendChild(gpArrowSvg);
      back.addEventListener('click',function(e){
        var ref=document.referrer;
        if(ref){try{var u=new URL(ref,location.href);if(u.origin===location.origin){e.preventDefault();history.back();}}catch(ignore){}}
      });
      var name=document.createElement('h1');
      name.className='gp-label-heading-name';
      name.textContent=label;
      heading.appendChild(back);
      heading.appendChild(name);
    } else {
      var nameEl=heading.querySelector('.gp-label-heading-name');
      if(nameEl)nameEl.textContent=label;
    }
    if(heading.parentNode!==container.parentNode || heading.nextElementSibling!==container){
      container.parentNode.insertBefore(heading,container);
    }
    return true;
  }
  function start(){
    if(addHeading())return;
    var attempts=0;
    var timer=setInterval(function(){attempts++;if(addHeading()||attempts>40)clearInterval(timer);},150);
    if(window.MutationObserver){
      var observer=new MutationObserver(function(){if(addHeading())observer.disconnect();});
      observer.observe(document.documentElement,{childList:true,subtree:true});
      setTimeout(function(){observer.disconnect();},8000);
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});
  else start();
})();

html.script:
//
(function(){
  function init(){
    var form=document.querySelector('#gp-global-header form.gp-search');
    if(!form) return;
    var input=form.querySelector('input[name="q"]');
    var list=form.querySelector('.gp-search-suggestions');
    if(!input || !list) return;

    var entries=[], loaded=false, loading=false, failed=false;
    function clean(v){return (v||'').toLocaleLowerCase().replace(/\s+/g,' ').trim();}
    function hide(){list.classList.remove('gp-open');list.innerHTML='';}
    function showMessage(msg){
      list.innerHTML='';
      var li=document.createElement('li');
      li.className='gp-empty';li.textContent=msg;list.appendChild(li);
      list.classList.add('gp-open');
    }
    function render(){
      var query=clean(input.value);
      list.innerHTML='';
      if(!query){hide();return;}
      if(!loaded){showMessage('Loading suggestions…');return;}
      var terms=query.split(' ');
      var found=entries.filter(function(post){
        var title=clean(post.title);
        var titleWords=title.split(' ');
        // A single typed letter matches titles beginning with that letter;
        // longer queries match the beginning of any word in the title.
        if(terms.length===1 && query.length===1) return title.indexOf(query)===0;
        return title.indexOf(query)!==-1 || terms.every(function(term){
          return titleWords.some(function(word){return word.indexOf(term)===0;});
        });
      }).slice(0,15);
      if(!found.length){showMessage('No matching posts');return;}
      found.forEach(function(post){
        var li=document.createElement('li');
        var button=document.createElement('button');
        button.type='button';button.textContent=post.title;
        button.addEventListener('click',function(){window.location.href=post.url;});
        li.appendChild(button);list.appendChild(li);
      });
      list.classList.add('gp-open');
    }
    function load(){
      if(loaded || loading || failed) return;
      loading=true;
      fetch('/feeds/posts/summary?alt=json&max-results=500')
        .then(function(response){if(!response.ok) throw new Error('Feed unavailable');return response.json();})
        .then(function(data){
          var raw=(data && data.feed && data.feed.entry) || [];
          entries=raw.map(function(entry){
            var alternate=(entry.link||[]).filter(function(link){return link.rel==='alternate';})[0];
            return {title:(entry.title && entry.title.$t)||'',url:alternate && alternate.href};
          }).filter(function(post){return post.title && post.url;});
          loaded=true;loading=false;
          if(input.value.trim()) render();
        })
        .catch(function(){loading=false;failed=true;hide();});
    }
    input.addEventListener('focus',function(){load();if(input.value.trim())render();});
    input.addEventListener('input',function(){load();render();});
    input.addEventListener('keydown',function(event){
      if(event.key==='Escape') hide();
    });
    document.addEventListener('click',function(event){if(!form.contains(event.target)) hide();});
    form.addEventListener('submit',function(){hide();});
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init);
  else init();
})();
